svg.script:
(function () {
  var W = 4, CELL = 79, GAP = 8, STEP = 87;
  var tiles = document.getElementById('tiles');
  var scoreT = document.getElementById('score'), overlay = document.getElementById('overlay');
  var grid = [], score = 0, over = false, won = false, started = false;
  var maxTile = 0;
  var COLORS = {
    2:'#333a47', 4:'#3d4656', 8:'#c0431e', 16:'#e05730', 32:'#ff6643',
    64:'#ffbe99', 128:'#ffd166', 256:'#ff9f1c', 512:'#ff6b6b', 1024:'#f43f5e', 2048:'#f43f5e'
  };

  // —— retention + contact (shared pattern) ——
  var GAME = '2048', DAILY_TARGET = 512;
  var DAILY_GAMES = ['snake', '2048', 'pong', 'abtest', 'funnel', 'cohort', 'sql', 'metric', 'retention', 'bottleneck'];
  var LS_BEST = 'arcade_best_' + GAME;
  var cta = document.getElementById('cta');
  var IS_LOCAL = /^(localhost|127\.0\.0\.1|::1|0\.0\.0\.0)$/.test(window.location.hostname);
  var PH_KEY = 'phc_tdju2w288PnkFE2e96efWKpoCvBPHPtveSztZK9NnGrv';
  if (!IS_LOCAL && PH_KEY.indexOf('__PH_') !== 0 && !window.posthog) {
    try {
      var phs = document.createElementNS('http://www.w3.org/2000/svg', 'script');
      phs.setAttribute('href', 'https://us-assets.i.posthog.com/static/array.js');
      phs.setAttribute('type', 'text/javascript');
      phs.onload = function () { try { window.posthog.init(PH_KEY, { defaults: '2026-05-30', persistence: 'localStorage+cookie', api_host: 'https://us.i.posthog.com', capture_pageview: true, capture_pageleave: true, autocapture: true, capture_exceptions: true, session_recording: { maskAllInputs: true } }); } catch (e) {} };
      document.documentElement.appendChild(phs);
    } catch (e) {}
  }
  function ph(name, props) { try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {} }
  function lsGet(k, d) { try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function bestOf() { return parseInt(lsGet(LS_BEST, '0'), 10) || 0; }
  function todayStr() { var n = new Date(); return n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  function todayGame() { return DAILY_GAMES[Math.floor(Date.now() / 86400000) % DAILY_GAMES.length]; }
  function markDaily() {
    var t = todayStr();
    var y = new Date(); y.setDate(y.getDate() - 1);
    var yst = y.getFullYear() + '-' + ('0' + (y.getMonth() + 1)).slice(-2) + '-' + ('0' + y.getDate()).slice(-2);
    var streak = lsGet('arcade_daily_date', '') === yst ? (parseInt(lsGet('arcade_streak', '0'), 10) || 0) + 1 : 1;
    lsSet('arcade_daily_date', t); lsSet('arcade_daily_done', '1'); lsSet('arcade_streak', String(streak));
    ph('daily_completed', { game: GAME, streak: streak });
  }
  function showCTA(on) { if (cta) cta.style.display = on ? 'block' : 'none'; }
  function wireCTA() {
    if (!cta) return;
    var links = cta.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function () {
        var href = this.getAttribute('href') || '';
        var channel = href.indexOf('linkedin') !== -1 ? 'linkedin' : (href.indexOf('t.me') !== -1 ? 'telegram' : 'other');
        ph('contact_click', { location: 'game_over', channel: channel, game: GAME });
      });
    }
  }
  var winFired = false, overFired = false;
  function finish(kind) {
    if (kind === 'over') { if (overFired) return; overFired = true; }
    if (kind === 'win') { if (winFired) return; winFired = true; }
    var best = bestOf();
    var newBest = score > best;
    if (newBest) { lsSet(LS_BEST, String(score)); ph('best_broken', { game: GAME, old_best: best, new_best: score, score: score }); }
    var isDaily = todayGame() === GAME && maxTile >= DAILY_TARGET;
    if (isDaily) markDaily();
    showCTA(newBest || kind === 'win');
    ph(kind === 'win' ? 'game_win' : 'game_over', { game: GAME, score: score, max_tile: maxTile, new_best: newBest, daily_done: !!isDaily });
  }
  // —— /retention ——

  function empty() {
    grid = []; for (var i = 0; i < W; i++) grid.push([0, 0, 0, 0]);
    score = 0; over = false; won = false; started = false;
    winFired = false; overFired = false; maxTile = 0;
    scoreT.textContent = 'Score: 0 · Best: ' + bestOf();
    overlay.textContent = 'Swipe or arrow keys to move';
    overlay.setAttribute('fill', '#f4f4f5');
    showCTA(false);
  }

  function spawn() {
    var cells = [];
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) if (!grid[i][j]) cells.push([i, j]);
    if (!cells.length) return;
    var c = cells[Math.floor(Math.random() * cells.length)];
    grid[c[0]][c[1]] = Math.random() < 0.9 ? 2 : 4;
  }

  function slide(a) {
    var out = [];
    for (var i = 0; i < a.length; i++) if (a[i]) out.push(a[i]);
    var merged = [];
    for (var i = 0; i < out.length; i++) {
      if (i + 1 < out.length && out[i] === out[i + 1]) { merged.push(out[i] * 2); score += out[i] * 2; i++; }
      else merged.push(out[i]);
    }
    while (merged.length < W) merged.push(0);
    return merged;
  }

  function move(dir) {
    var moved = false;
    for (var i = 0; i < W; i++) {
      var r, c, dr, dc;
      if (dir === 'up') { r = 0; c = i; dr = 1; dc = 0; }
      else if (dir === 'down') { r = W - 1; c = i; dr = -1; dc = 0; }
      else if (dir === 'left') { r = i; c = 0; dr = 0; dc = 1; }
      else { r = i; c = W - 1; dr = 0; dc = -1; }
      var a = [];
      for (var k = 0; k < W; k++) a.push(grid[r + dr * k][c + dc * k]);
      var na = slide(a);
      for (var k = 0; k < W; k++) {
        if (grid[r + dr * k][c + dc * k] !== na[k]) moved = true;
        grid[r + dr * k][c + dc * k] = na[k];
      }
    }
    if (moved) { spawn(); scoreT.textContent = 'Score: ' + score + ' · Best: ' + Math.max(bestOf(), score); checkEnd(); draw(); }
  }

  function checkEnd() {
    maxTile = 0;
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) {
      maxTile = Math.max(maxTile, grid[i][j]);
      if (grid[i][j] === 2048 && !won) {
        won = true;
        overlay.textContent = '2048! You did it · tap to continue';
        finish('win');
      }
      if (!grid[i][j]) return;
      if (j + 1 < W && grid[i][j] === grid[i][j + 1]) return;
      if (i + 1 < W && grid[i][j] === grid[i + 1][j]) return;
    }
    over = true;
    finish('over');
    overlay.textContent = 'Game over · tap to restart';
    overlay.setAttribute('fill', '#ff4b4b');
  }

  function draw() {
    while (tiles.firstChild) tiles.removeChild(tiles.firstChild);
    for (var i = 0; i < W; i++) for (var j = 0; j < W; j++) {
      var x = j * STEP, y = i * STEP;
      if (!grid[i][j]) {
        var bg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        bg.setAttribute('x', x); bg.setAttribute('y', y);
        bg.setAttribute('width', CELL); bg.setAttribute('height', CELL);
        bg.setAttribute('rx', 6); bg.setAttribute('fill', '#1a1f2a');
        tiles.appendChild(bg);
        continue;
      }
      var v = grid[i][j];
      var t = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      t.setAttribute('x', x); t.setAttribute('y', y);
      t.setAttribute('width', CELL); t.setAttribute('height', CELL);
      t.setAttribute('rx', 6);
      t.setAttribute('fill', COLORS[v] || '#f43f5e');
      tiles.appendChild(t);
      var s = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      var fs = ('' + v).length <= 2 ? 30 : ('' + v).length === 3 ? 24 : 20;
      s.setAttribute('x', x + CELL / 2); s.setAttribute('y', y + CELL / 2 + 10);
      s.setAttribute('text-anchor', 'middle');
      s.setAttribute('font-size', fs);
      s.setAttribute('font-weight', 'bold');
      s.setAttribute('fill', v >= 64 ? '#0a0a12' : '#f4f4f5');
      s.textContent = v;
      tiles.appendChild(s);
    }
  }

  document.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowUp' || k === 'w' || k === 'W') { e.preventDefault(); move('up'); }
    else if (k === 'ArrowDown' || k === 's' || k === 'S') { e.preventDefault(); move('down'); }
    else if (k === 'ArrowLeft' || k === 'a' || k === 'A') { e.preventDefault(); move('left'); }
    else if (k === 'ArrowRight' || k === 'd' || k === 'D') { e.preventDefault(); move('right'); }
    else if (k === 'r' || k === 'R') { empty(); spawn(); spawn(); draw(); }
    if (!started && !over) { started = true; ph('game_started', { game: GAME }); }
  });

  // --- Touch controls (mobile) ---
  var tsx = 0, tsy = 0;
  document.addEventListener('touchstart', function (e) { tsx = e.touches[0].clientX; tsy = e.touches[0].clientY; }, {passive: true});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); }, {passive: false});
  document.addEventListener('touchend', function (e) {
    var t = e.changedTouches[0];
    var dx = t.clientX - tsx, dy = t.clientY - tsy;
    if (Math.abs(dx) < 24 && Math.abs(dy) < 24) { if (over) { empty(); spawn(); spawn(); draw(); } return; }
    if (!started && !over) { started = true; ph('game_started', { game: GAME }); }
    if (Math.abs(dx) > Math.abs(dy)) move(dx > 0 ? 'right' : 'left');
    else move(dy > 0 ? 'down' : 'up');
  }, {passive: false});

  wireCTA();
  empty(); spawn(); spawn(); draw();
})();
